/// <summary>
/// PaffH 24.04.25
/// disable FormCheckBoxFilterMarked
/// </summary>
public void clicked()
{
    super();
    if (!this.checked())
    {
        FormCheckBoxControl control = element.design().controlName(formcontrolstr(NDXPOPspecificDataManagement, FormCheckBoxFilterMarked)) as FormCheckBoxControl;
        if (control.checked())
        {
            control.value(0);
        }
    }
}

